// 18-tap direct-form FIR, 8-bit samples, unpipelined MAC cone (the long
// register-to-register path -> lower Fmax; pipeline it to go faster).
module firr18_v5 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg  [7:0]  xs [0:17];
    integer     i;
    reg  [23:0] acc;
    always @(*) acc = 24'd0 +
        (24'd3 * xs[0]) +
        (24'd9 * xs[1]) +
        (24'd17 * xs[2]) +
        (24'd27 * xs[3]) +
        (24'd39 * xs[4]) +
        (24'd53 * xs[5]) +
        (24'd69 * xs[6]) +
        (24'd87 * xs[7]) +
        (24'd107 * xs[8]) +
        (24'd129 * xs[9]) +
        (24'd153 * xs[10]) +
        (24'd179 * xs[11]) +
        (24'd207 * xs[12]) +
        (24'd237 * xs[13]) +
        (24'd269 * xs[14]) +
        (24'd303 * xs[15]) +
        (24'd339 * xs[16]) +
        (24'd377 * xs[17]);
    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 18; i = i + 1) xs[i] <= 8'd0;
            y <= 16'd0;
        end else begin
            xs[0] <= x;
            for (i = 1; i < 18; i = i + 1) xs[i] <= xs[i-1];
            y <= acc[15:0];
        end
    end
endmodule
